<?php
namespace Core;require_once __DIR__.'/Guard.php';require_once __DIR__.'/CurlSafe.php';ml_guard_shield(__FILE__);class Http{private static $lastMeta=array();public static function get($a,array $b=[],$c=3){$d=max(1,min(4,(int)$c));$e=0;$f=1;$g=array();$h=microtime(true);while($e<$d){$e++;$i=CurlSafe::request($a,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>20,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_HTTPHEADER=>$b,CURLOPT_USERAGENT=>'MediaLibraryAPI/1.0',],20);$j=$i['body'];$k=(int)$i['code'];$l=(string)$i['err'];$m=false;$n='';if(!is_string($j)||$j===''){$m=true;$n=$l!==''?$l:'empty response';}elseif(in_array($k,array(408,425,429,500,502,503,504,520,521,522,523,524),true)){$m=true;$n='HTTP '.$k;}else{$o=json_decode($j,true);if(is_array($o)){self::$lastMeta=array('attempts'=>$e,'max_attempts'=>$d,'retries'=>$e-1,'retry_reasons'=>$g,'code'=>$k,'ms'=>(int)round((microtime(true)-$h)*1000),);return array('code'=>$k,'data'=>$o);}$m=true;$n='invalid JSON';}if(!$m||$e>=$d){$p=$g;if($m&&$n!==''){$p[]=$n;}self::$lastMeta=array('attempts'=>$e,'max_attempts'=>$d,'retries'=>$e-1,'retry_reasons'=>$p,'code'=>$k,'ms'=>(int)round((microtime(true)-$h)*1000),);throw new \RuntimeException(self::describeFailure($n,$k,$j,$a));}$g[]=$n;sleep($f);$f=min($f*2,4);}throw new \RuntimeException("HTTP request failed after retries: $a");}private static function describeFailure($a,$b,$c,$d){$e=$b>0?"HTTP {$b}":'无 HTTP 状态码';$f='';if(is_string($c)&&$c!==''){$g=preg_replace('/[\x00-\x1f\x7f]+/u',' ',$c);$g=trim(preg_replace('/\s+/u',' ',$g));if($g!==''){$f=' | 上游响应: '.mb_substr($g,0,120);}}$h='请求失败';if($a==='invalid JSON'){$h='上游响应不是合法 JSON';}elseif($a==='empty response'){$h='上游返回空响应';}elseif($a!==''){$h=$a;}return"{$h}（{$e}）{$f} ({$d})";}}